import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;

public class ReportServlet extends HttpServlet {

    private static final Pattern SAFE_ORDER = Pattern.compile("^(date|amount|status)$");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) 
            throws ServletException, IOException {

        String customerId = req.getParameter("customer_id");
        String startDate = req.getParameter("start_date");
        String endDate = req.getParameter("end_date");
        String orderBy = req.getParameter("order_by");
        String filterExpr = req.getParameter("filter");

        // Validate order_by against whitelist
        if (orderBy != null && !SAFE_ORDER.matcher(orderBy).matches()) {
            orderBy = "date";
        }
        if (orderBy == null) orderBy = "date";

        // Build report query
        StringBuilder query = new StringBuilder();
        query.append("SELECT transaction_id, date, amount, status, description ");
        query.append("FROM transactions WHERE customer_id = ? ");

        if (startDate != null && endDate != null) {
            query.append("AND date BETWEEN ? AND ? ");
        }

        // Advanced filter - allows custom SQL expressions for power users
        // This is intentionally flexible for complex reporting needs
        if (filterExpr != null && !filterExpr.isEmpty()) {
            // Basic sanitization: remove comments and semicolons
            String cleaned = filterExpr.replaceAll("--", "").replaceAll(";", "");
            // Remove obvious dangerous keywords (case insensitive)
            cleaned = cleaned.replaceAll("(?i)(DROP|ALTER|TRUNCATE|CREATE|GRANT)", "");
            query.append("AND (").append(cleaned).append(") ");
        }

        query.append("ORDER BY ").append(orderBy).append(" DESC");

        Connection conn = null;
        PreparedStatement stmt = null;
        ResultSet rs = null;

        try {
            conn = getDataSource().getConnection();
            stmt = conn.prepareStatement(query.toString());

            int paramIdx = 1;
            stmt.setString(paramIdx++, customerId);
            if (startDate != null && endDate != null) {
                stmt.setString(paramIdx++, startDate);
                stmt.setString(paramIdx++, endDate);
            }

            rs = stmt.executeQuery();

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                out.printf("  {\"id\": \"%s\", \"date\": \"%s\", \"amount\": %s, \"status\": \"%s\", \"desc\": \"%s\"}",
                    rs.getString(1), rs.getString(2), rs.getBigDecimal(3), 
                    rs.getString(4), rs.getString(5));
                first = false;
            }
            out.print("\n]");

        } catch (SQLException e) {
            resp.setStatus(500);
            resp.getWriter().write("{\"error\": \"Query failed\"}");
        } finally {
            if (rs != null) try { rs.close(); } catch (SQLException e) {}
            if (stmt != null) try { stmt.close(); } catch (SQLException e) {}
            if (conn != null) try { conn.close(); } catch (SQLException e) {}
        }
    }

    private javax.sql.DataSource getDataSource() throws SQLException {
        try {
            javax.naming.Context ctx = new javax.naming.InitialContext();
            return (javax.sql.DataSource) ctx.lookup("java:comp/env/jdbc/reportdb");
        } catch (javax.naming.NamingException e) {
            throw new SQLException("DataSource lookup failed", e);
        }
    }
}
